// Bundles content/legal/<locale>/<document>.md into lib/legal-bundle.gen.ts.
// A Cloudflare Worker cannot read files while serving, so the text has to be part of the build.
//   node scripts/legal-bundle.mjs          write the file
//   node scripts/legal-bundle.mjs --check  fail if the file is out of date (run by `npm run check`)
import { execFileSync } from 'node:child_process';
import { existsSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const LOCALES = ['en', 'th'];
const DOCUMENTS = ['terms', 'privacy'];
const target = path.join(root, 'lib', 'legal-bundle.gen.ts');

const sources = Object.fromEntries(
  LOCALES.map((locale) => [
    locale,
    Object.fromEntries(
      DOCUMENTS.map((document) => [
        document,
        readFileSync(path.join(root, 'content', 'legal', locale, `${document}.md`), 'utf8'),
      ])
    ),
  ])
);

const output = `// Generated by scripts/legal-bundle.mjs from content/legal. Do not edit; run \`npm run legal:generate\`.
export const LEGAL_SOURCES = ${JSON.stringify(sources, null, 2)} as const;
`;
writeFileSync(path.join(root, 'lib', '.legal-bundle.tmp.ts'), output);
execFileSync('npx', ['prettier', '--write', path.join(root, 'lib', '.legal-bundle.tmp.ts')], { stdio: 'ignore' });
const formatted = readFileSync(path.join(root, 'lib', '.legal-bundle.tmp.ts'), 'utf8');
execFileSync('rm', [path.join(root, 'lib', '.legal-bundle.tmp.ts')]);

if (process.argv.includes('--check')) {
  const current = existsSync(target) ? readFileSync(target, 'utf8') : '';
  if (current !== formatted) {
    console.error('lib/legal-bundle.gen.ts is out of date. Run `npm run legal:generate`.');
    process.exit(1);
  }
} else {
  writeFileSync(target, formatted);
}
